import{_ as t,o as l,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const s="/assets/image-ubuntu240801.CMRvF4GE.png",r="/assets/image-ubuntu240802.-Bc6WUj1.png",n="/assets/image-ubuntu240803.BGlfStiq.png",i="/assets/image-ubuntu240804.eZ5hn6pN.png",p="/assets/image-ubuntu240805.Dpls2RFb.png",h=JSON.parse('{"title":"Enable/Disable Firewall and Modify Remote Port in Ubuntu 18.04-22.04","description":"","frontmatter":{"title":"Enable/Disable Firewall and Modify Remote Port in Ubuntu 18.04-22.04"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/enable-disable-firewall-and-modify-remote-port-in-ubuntu-18-04-22-04.md","filePath":"operations-knowledge-base/operating-system/linux/enable-disable-firewall-and-modify-remote-port-in-ubuntu-18-04-22-04.md","lastUpdated":1794292919000}'),u={name:"operations-knowledge-base/operating-system/linux/enable-disable-firewall-and-modify-remote-port-in-ubuntu-18-04-22-04.md"};function m(w,e,c,d,f,b){return l(),o("div",null,[...e[0]||(e[0]=[a('<p>In Ubuntu 18.04-22.04, the default firewall system is <strong>ufw (Uncomplicated Firewall)</strong>. Taking Ubuntu 18.04 as an example, it can be configured as shown in the following picture:</p><p><img src="'+s+'" alt=""></p><ol><li>Check the Firewall Status (Default is Disabled) #ufw status</li></ol><p><img src="'+r+'" alt=""></p><ol start="2"><li>Enable the Firewall</li></ol><p>#ufw enable</p><p><img src="'+n+'" alt=""></p><p>3.Disable the Firewall</p><p>#Ufw disable</p><p><img src="'+i+'" alt=""></p><p>4.If the firewall is enabled, the commands to allow a specific port are as follows:</p><p>ufw allow 80/tcp ##Allow port 80 ufw allow 22/tcp ##Allow port 22 ufw allow 8112/tcp ##Allow port 8112 ufw allow 1000:2000/tcp ##Allow the port range 1000 to 2000.</p><p>5.The commands to delete an allowed port are as follows:</p><p>ufw delete allow 80/tcp ##Delete the rule allowing port 80 ufw delete allow 22/tcp ##Delete the rule allowing port 22 ufw delete allow 1000:2000/tcp ##Delete the rule allowing the port range 1000:2000</p><p>6.Modify the remote SSH port, restart the SSH service, and allow the new remote port.</p><p>For example, if the current remote port is 22 and you need to change it to 2882, the commands are as follows: sed -i &#39;s/^Port 22/Port 2882/&#39; /etc/ssh/sshd_config ##Modify the remote port systemctl restart sshd ##restart the SSH service ufw allow 2882/tcp ##allow the new remote port</p><p><img src="'+p+'" alt=""></p><p>7.Use the new port for remote login.</p><p>ssh root@ specific IP -p 2882</p><p>(The above operations are also applicable to Debian 10-12 systems.)</p>',20)])])}const _=t(u,[["render",m]]);export{h as __pageData,_ as default};
